const appearanceBeforeBackground=settingPage;settingPage=function(){const html=appearanceBeforeBackground();if(screen!=='setting-appearance')return html;return html+'<div class="option-row"><div><strong>Анимация фона</strong><small>Медленные мягкие переливы.</small></div><div class="toggle-target">'+btn('background-motion','<span class="switch-track"><span></span></span>','toggle','role="switch" aria-label="Анимация фона" aria-checked="'+state.backgroundMotion+'"')+'</div></div>';};
let observedOrb=null,orbObserver=null,lastMenu=null,lastMenuKey='';
function watchOrb(){const control=root.querySelector('.aurora-button');if(control===observedOrb)return;orbObserver?.disconnect();orbObserver=null;observedOrb=control;document.documentElement.classList.remove('orb-outside');if(control&&typeof IntersectionObserver==='function'){orbObserver=new IntersectionObserver(entries=>{document.documentElement.classList.toggle('orb-outside',!entries[0].isIntersecting);},{root:root.querySelector('.content'),threshold:.02});orbObserver.observe(control);}}
const renderBeforeAmbient=render;render=function(){renderBeforeAmbient();document.documentElement.classList.toggle('orb-preview-animation',connection==='pending'&&sheet?.kind==='connect-demo');document.documentElement.classList.toggle('ambient-static',!state.backgroundMotion);watchOrb();const menu=root.querySelector('.context-menu'),key=sheet?.kind==='menu'?sheet.objectKind+':'+sheet.id:'';if(menu&&(menu!==lastMenu||key!==lastMenuKey)){const box=menu.getBoundingClientRect?.(),point=sheet.position;menu.style.transformOrigin=(box&&point?(point.x>box.left+box.width/2?'right':'left')+' '+(point.y>box.top+box.height/2?'bottom':'top'):'top left');animateOnce('menu',menu,{opacity:[0,1],scale:[.96,1],y:[4,0]},{duration:.16,ease:'easeOut'});}if(!menu)stop('menu');lastMenu=menu;lastMenuKey=key;};
const backBeforeMenuFade=back;back=function(fromHistory=false){
  const menu=root.querySelector('.context-menu');
  if(sheet?.kind==='menu'&&sheet.closing){if(fromHistory){stop('menu');delete sheet.closing;backBeforeMenuFade(true);}return;}
  if(sheet?.kind==='menu'&&!fromHistory&&canAnimate(menu)){const target=sheet;target.closing=true;const control=animateOnce('menu',menu,{opacity:0,scale:.98},{duration:.12,ease:'easeIn'});if(control){control.finished.then(()=>{if(sheet===target){delete target.closing;backBeforeMenuFade(false);}},()=>{if(sheet===target){delete target.closing;backBeforeMenuFade(false);}});return;}delete target.closing;}
  backBeforeMenuFade(fromHistory);
};
root.addEventListener('scroll',event=>{if(orbObserver||event.target!==root.querySelector('.content'))return;const orb=root.querySelector('.aurora-button'),main=root.querySelector('.content');if(!orb?.getBoundingClientRect||!main?.getBoundingClientRect)return;const a=orb.getBoundingClientRect(),b=main.getBoundingClientRect();document.documentElement.classList.toggle('orb-outside',a.bottom<=b.top||a.top>=b.bottom);},true);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&sheet?.kind==='menu'&&sheet.closing){delete sheet.closing;backBeforeMenuFade(false);}});
